ALTER TABLE focus_sessions ADD COLUMN task_id INTEGER REFERENCES tasks(id) ON DELETE SET NULL;
ALTER TABLE focus_sessions ADD COLUMN habit_id INTEGER REFERENCES planner_habits(id) ON DELETE SET NULL;
ALTER TABLE focus_sessions ADD COLUMN habit_minimum_minutes INTEGER NOT NULL DEFAULT 25 CHECK(habit_minimum_minutes BETWEEN 1 AND 120);
CREATE TABLE focus_task_logs(session_id INTEGER PRIMARY KEY REFERENCES focus_sessions(id) ON DELETE CASCADE,task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,seconds INTEGER NOT NULL CHECK(seconds>0),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE focus_habit_events(session_id INTEGER PRIMARY KEY REFERENCES focus_sessions(id) ON DELETE CASCADE,habit_id INTEGER NOT NULL REFERENCES planner_habits(id) ON DELETE CASCADE,date TEXT NOT NULL,seconds INTEGER NOT NULL CHECK(seconds>0),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
